import { db } from './db.ts';

export interface TelegramSendMessageOptions {
  parse_mode?: 'HTML' | 'Markdown' | 'MarkdownV2';
  disable_web_page_preview?: boolean;
  reply_markup?: any;
  reply_to_message_id?: number;
}

export class TelegramClient {
  private getBotToken(overrideToken?: string): string {
    const token = overrideToken || process.env.TELEGRAM_BOT_TOKEN || db.getSettings().botToken;
    if (!token || token.trim() === '' || token.includes('TODO')) {
      throw new Error('Telegram Bot Token is not configured. Set TELEGRAM_BOT_TOKEN in .env or configure in Admin Panel.');
    }
    return token.trim();
  }

  public hasValidToken(overrideToken?: string): boolean {
    try {
      const token = this.getBotToken(overrideToken);
      return token.length > 20 && token.includes(':');
    } catch {
      return false;
    }
  }

  private async callApi(endpoint: string, payload: any, overrideToken?: string): Promise<any> {
    const token = this.getBotToken(overrideToken);
    const url = `https://api.telegram.org/bot${token}/${endpoint}`;

    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    const json: any = await res.json();
    if (!json.ok) {
      const desc = json.description || 'Unknown Telegram error';
      const code = json.error_code || res.status;
      const error = new Error(`Telegram API [${code}]: ${desc}`);
      (error as any).errorCode = code;
      (error as any).parameters = json.parameters;
      throw error;
    }
    return json.result;
  }

  public async getMe(overrideToken?: string): Promise<any> {
    const token = this.getBotToken(overrideToken);
    const res = await fetch(`https://api.telegram.org/bot${token}/getMe`);
    const json: any = await res.json();
    if (!json.ok) {
      throw new Error(`Telegram getMe error: ${json.description}`);
    }
    return json.result;
  }

  public async getChat(chatId: string | number, overrideToken?: string): Promise<any> {
    const formattedChatId = this.formatChatId(chatId);
    return this.callApi('getChat', { chat_id: formattedChatId }, overrideToken);
  }

  public async getChatMember(chatId: string | number, userId: string | number, overrideToken?: string): Promise<any> {
    const formattedChatId = this.formatChatId(chatId);
    return this.callApi('getChatMember', { chat_id: formattedChatId, user_id: userId }, overrideToken);
  }

  public async verifyChannelPermissions(chatId: string | number, overrideToken?: string): Promise<{
    canPost: boolean;
    chatTitle: string;
    chatType: string;
    error?: string;
  }> {
    try {
      const me = await this.getMe(overrideToken);
      const chat = await this.getChat(chatId, overrideToken);
      const member = await this.getChatMember(chatId, me.id, overrideToken);

      const status = member.status; // 'creator', 'administrator', 'member', etc.
      const canPost =
        status === 'creator' ||
        (status === 'administrator' && (member.can_post_messages !== false));

      return {
        canPost,
        chatTitle: chat.title || chat.username || String(chatId),
        chatType: chat.type,
      };
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      return {
        canPost: false,
        chatTitle: String(chatId),
        chatType: 'unknown',
        error: message,
      };
    }
  }

  public async sendMessage(
    chatId: string | number,
    text: string,
    options?: TelegramSendMessageOptions,
    overrideToken?: string
  ): Promise<any> {
    const formattedChatId = this.formatChatId(chatId);
    const parseMode = options?.parse_mode || 'HTML';

    // Chunk message if exceeds Telegram's 4096 character limit
    const MAX_CHUNK = 4000;
    if (text.length > MAX_CHUNK) {
      const chunks = this.splitMessage(text, MAX_CHUNK);
      let lastResult: any = null;
      for (let i = 0; i < chunks.length; i++) {
        lastResult = await this.sendSingleMessage(
          formattedChatId,
          chunks[i],
          { ...options, reply_markup: i === chunks.length - 1 ? options?.reply_markup : undefined },
          overrideToken
        );
      }
      return lastResult;
    }

    return this.sendSingleMessage(formattedChatId, text, options, overrideToken);
  }

  private async sendSingleMessage(
    chatId: string | number,
    text: string,
    options?: TelegramSendMessageOptions,
    overrideToken?: string
  ): Promise<any> {
    try {
      return await this.callApi(
        'sendMessage',
        {
          chat_id: chatId,
          text,
          parse_mode: options?.parse_mode || 'HTML',
          disable_web_page_preview: options?.disable_web_page_preview,
          reply_markup: options?.reply_markup,
          reply_to_message_id: options?.reply_to_message_id,
        },
        overrideToken
      );
    } catch (err: any) {
      // If parsing fails (e.g. invalid HTML tags or unmatched markdown), fallback to plain text safely
      if (err.message && err.message.toLowerCase().includes("can't parse entities")) {
        db.logSystem('warn', 'telegram_bot', `Telegram parse error on entity tags; retrying as clean text`);
        const cleanText = text.replace(/<[^>]*>/g, '');
        return await this.callApi(
          'sendMessage',
          {
            chat_id: chatId,
            text: cleanText,
            disable_web_page_preview: options?.disable_web_page_preview,
            reply_markup: options?.reply_markup,
            reply_to_message_id: options?.reply_to_message_id,
          },
          overrideToken
        );
      }
      throw err;
    }
  }

  public async sendPhoto(
    chatId: string | number,
    photoUrlOrBuffer: string | Buffer,
    caption?: string,
    options?: TelegramSendMessageOptions,
    overrideToken?: string
  ): Promise<any> {
    const formattedChatId = this.formatChatId(chatId);

    if (typeof photoUrlOrBuffer === 'string') {
      try {
        return await this.callApi(
          'sendPhoto',
          {
            chat_id: formattedChatId,
            photo: photoUrlOrBuffer,
            caption: caption ? caption.slice(0, 1024) : undefined,
            parse_mode: options?.parse_mode || 'HTML',
            reply_markup: options?.reply_markup,
          },
          overrideToken
        );
      } catch (err: any) {
        // If remote URL is blocked or invalid, fallback to sending message with embedded link
        db.logSystem('warn', 'telegram_bot', `Remote photo send failed (${err.message}). Falling back to text link`);
        const fallbackText = caption ? `${caption}\n\n🖼️ Photo: ${photoUrlOrBuffer}` : `🖼️ Photo: ${photoUrlOrBuffer}`;
        return await this.sendMessage(formattedChatId, fallbackText, options, overrideToken);
      }
    } else {
      // Buffer upload via multipart FormData
      const token = this.getBotToken(overrideToken);
      const formData = new FormData();
      formData.append('chat_id', String(formattedChatId));
      if (caption) formData.append('caption', caption.slice(0, 1024));
      if (options?.parse_mode) formData.append('parse_mode', options.parse_mode);
      const blob = new Blob([photoUrlOrBuffer]);
      formData.append('photo', blob, 'image.jpg');

      const res = await fetch(`https://api.telegram.org/bot${token}/sendPhoto`, {
        method: 'POST',
        body: formData,
      });
      const json: any = await res.json();
      if (!json.ok) throw new Error(`Telegram sendPhoto Buffer error: ${json.description}`);
      return json.result;
    }
  }

  public async sendVideo(
    chatId: string | number,
    videoUrl: string,
    caption?: string,
    options?: TelegramSendMessageOptions,
    overrideToken?: string
  ): Promise<any> {
    const formattedChatId = this.formatChatId(chatId);
    try {
      return await this.callApi(
        'sendVideo',
        {
          chat_id: formattedChatId,
          video: videoUrl,
          caption: caption ? caption.slice(0, 1024) : undefined,
          parse_mode: options?.parse_mode || 'HTML',
          reply_markup: options?.reply_markup,
        },
        overrideToken
      );
    } catch (err: any) {
      db.logSystem('warn', 'telegram_bot', `Remote video send failed (${err.message}). Falling back to text link`);
      const fallbackText = caption ? `${caption}\n\n🎥 Video: ${videoUrl}` : `🎥 Video: ${videoUrl}`;
      return await this.sendMessage(formattedChatId, fallbackText, options, overrideToken);
    }
  }

  public async sendMediaGroup(
    chatId: string | number,
    mediaList: Array<{ type: 'photo' | 'video'; url: string; caption?: string }>,
    options?: TelegramSendMessageOptions,
    overrideToken?: string
  ): Promise<any> {
    const formattedChatId = this.formatChatId(chatId);
    const mediaPayload = mediaList.slice(0, 10).map((m, idx) => ({
      type: m.type,
      media: m.url,
      caption: idx === 0 && m.caption ? m.caption.slice(0, 1024) : undefined,
      parse_mode: idx === 0 ? options?.parse_mode || 'HTML' : undefined,
    }));

    try {
      return await this.callApi(
        'sendMediaGroup',
        {
          chat_id: formattedChatId,
          media: mediaPayload,
        },
        overrideToken
      );
    } catch (err: any) {
      db.logSystem('warn', 'telegram_bot', `Media group send failed (${err.message}). Falling back to single photo`);
      if (mediaList.length > 0) {
        return await this.sendPhoto(formattedChatId, mediaList[0].url, mediaList[0].caption, options, overrideToken);
      }
      throw err;
    }
  }

  public async getFile(fileId: string, overrideToken?: string): Promise<{ filePath: string; fileUrl: string }> {
    const file = await this.callApi('getFile', { file_id: fileId }, overrideToken);
    const token = this.getBotToken(overrideToken);
    const fileUrl = `https://api.telegram.org/file/bot${token}/${file.file_path}`;
    return { filePath: file.file_path, fileUrl };
  }

  public async downloadFileBuffer(fileId: string, overrideToken?: string): Promise<Buffer> {
    const { fileUrl } = await this.getFile(fileId, overrideToken);
    const res = await fetch(fileUrl);
    if (!res.ok) throw new Error(`Failed to download file from Telegram: ${res.statusText}`);
    const arrayBuffer = await res.arrayBuffer();
    return Buffer.from(arrayBuffer);
  }

  public async setWebhook(url: string, overrideToken?: string): Promise<any> {
    return this.callApi(
      'setWebhook',
      {
        url,
        allowed_updates: ['message', 'channel_post', 'callback_query', 'my_chat_member'],
        drop_pending_updates: false,
      },
      overrideToken
    );
  }

  public async deleteWebhook(overrideToken?: string): Promise<any> {
    return this.callApi('deleteWebhook', { drop_pending_updates: false }, overrideToken);
  }

  public async getUpdates(offset?: number, limit = 100, timeout = 30, overrideToken?: string): Promise<any[]> {
    return this.callApi(
      'getUpdates',
      {
        offset,
        limit,
        timeout,
        allowed_updates: ['message', 'channel_post', 'callback_query', 'my_chat_member'],
      },
      overrideToken
    );
  }

  private formatChatId(chatId: string | number): string | number {
    if (typeof chatId === 'number') return chatId;
    const str = chatId.trim();
    if (str.startsWith('@') || /^-?\d+$/.test(str)) {
      return /^-?\d+$/.test(str) ? parseInt(str, 10) : str;
    }
    // If username without @ was passed, add @
    return `@${str}`;
  }

  private splitMessage(str: string, maxLength: number): string[] {
    const parts: string[] = [];
    let current = '';
    const paragraphs = str.split('\n\n');

    for (const para of paragraphs) {
      if ((current + '\n\n' + para).length <= maxLength) {
        current = current ? current + '\n\n' + para : para;
      } else {
        if (current) parts.push(current);
        if (para.length <= maxLength) {
          current = para;
        } else {
          // Break lines
          const lines = para.split('\n');
          current = '';
          for (const line of lines) {
            if ((current + '\n' + line).length <= maxLength) {
              current = current ? current + '\n' + line : line;
            } else {
              if (current) parts.push(current);
              current = line;
            }
          }
        }
      }
    }
    if (current) parts.push(current);
    return parts.length ? parts : [str];
  }
}

export const telegramClient = new TelegramClient();
